@layer components {
  :where([data-control-family="skeleton"][data-slot="root"]) {
    --skeleton-radius: var(--radius-control);
    --skeleton-background: var(--muted);
    border-radius: var(--skeleton-radius);
    background-color: var(--skeleton-background);
    background-image: linear-gradient(
      100deg,
      transparent 30%,
      oklch(from var(--foreground) l c h / 0.06) 50%,
      transparent 70%
    );
    background-size: 220% 100%;
    animation: shimmer calc(var(--duration-slow) * 5) var(--ease-standard) infinite;
  }

}

@property --skeleton-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --skeleton-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

import type { ComponentProps, CSSProperties } from "react";
import type { SkeletonKnobStyle } from "@/components/control-ui/knob-contracts";

export function Skeleton({ className, ...props }: Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & SkeletonKnobStyle }) {
  return <div data-control-ui="skeleton" data-control-family="skeleton" data-slot="root" className={className} {...props} />;
}
